    """整帧 v3 报告解析成功后，按报文顺序依次作用于入端口成员。

    每条记录都把对应成员的 expires 统一刷新为 t+membership_age。空
    INCLUDE 删除成员；空 EXCLUDE 以空源集合表示接收全部源。
    """
    for rtype, group, sources in records:
        key = (vlan, group)
        table = membership.get(key)
        source_set = set(sources)
        if rtype == IGMPV3_MODE_IS_INCLUDE:
            entry = (
                {"expires": t + membership_age, "mode": "include",
                 "sources": source_set}
                if source_set else None
            )
        elif rtype == IGMPV3_MODE_IS_EXCLUDE:
            entry = {
                "expires": t + membership_age, "mode": "exclude",
                "sources": source_set,
            }
        elif rtype == IGMPV3_CHANGE_TO_INCLUDE:
            entry = (
                {"expires": t + membership_age, "mode": "include",
                 "sources": source_set}
                if source_set else None
            )
        else:
            if rtype == IGMPV3_CHANGE_TO_EXCLUDE:
                new_mode, new_sources = "exclude", source_set
                replace = True
            else:
                entry = table.get(port_name) if table else None
                if entry is None:
                    # 完全无成员：以 INCLUDE 空集为基线应用增量
                    new_mode, current = "include", set()
                elif "mode" not in entry:
                    # 仅经 IGMPv2 建立的成员：v2 加入等价于
                    # EXCLUDE 空集（接收全部源）
                    new_mode, current = "exclude", set()
                else:
                    new_mode, current = entry["mode"], set(entry["sources"])
                if rtype == IGMPV3_ALLOW_NEW_SOURCES:
                    # INCLUDE 取并集；EXCLUDE 做差集（空集仍为
                    # EXCLUDE {}，表示接收全部源，不得删除成员）
                    if new_mode == "include":
                        new_sources = current | source_set
                    else:
                        new_sources = current - source_set
                else:  # BLOCK_OLD_SOURCES：INCLUDE 做差集；EXCLUDE 取并集
                    if new_mode == "include":
                        new_sources = current - source_set
                    else:
                        new_sources = current | source_set
                if new_mode == "include" and not new_sources:
                    replace, entry = True, None
                else:
                    replace = False
            if replace:
                entry = {
                    "expires": t + membership_age, "mode": new_mode,
                    "sources": new_sources,
                }
        if entry is None:  # 空 INCLUDE：删除成员
            if table is not None:
                table.pop(port_name, None)
                if not table:
                    del membership[key]
        else:
            membership.setdefault(key, {})[port_name] = entry
        affected.add(key)
    return affected

